import json,pathlib
P=pathlib.Path('research/asia');r=json.load(open(P/'reviews.json'))
def add(id,diff,reason,sol='',statement=None,topic=None,subtopics=None,**kw):
 r[id]={'difficulty':diff,'reason':reason,'proofConfidence':'checked' if diff is not None else 'unresolved',**kw}
 if sol:r[id]['solutionOverride']=sol
 if statement:r[id]['statementOverride']=statement
 if topic:r[id]['topic']=topic
 if subtopics:r[id]['subtopics']=subtopics;r[id]['tags']=subtopics
add('chn_2002_2488b3',3,'Parity and division with remainder reduce the problem to a short finite list of quotients and small positive values; none satisfies the divisibility.')
add('chn_2002_ea4526',None,'The downloaded statement and solution contain only part (1) of the numbered problem; the rest of the original multi-part task is not available.',omitReason='Held unrated as an incomplete question transcription. The nine-point part has the affine-plane construction over F3, but that does not establish assessment of the entire original question.')
add('chn_2002_1d1d7c',3.5,'For c=a+b+t the nontriangle obstruction is the identity 5Σa²−6Σab=4(a−b)²+4(a+b)t+5t²; the boundary triple (1,1,2) is sharp. The literal implication also includes the vacuous k≤5 cases.',note='The supplied solution incorrectly discards vacuous cases. Under the displayed quantified statement the answer is k=1,2,3,4,5,6; if existence of a qualifying triple was intended, only k=6 remains.')
